function getErrorMessage(error: unknown) { return error instanceof Error ? error.message : 'Something went wrong. Please try again.'; }
function createSafeStorageName() { if ('randomUUID' in crypto) return crypto.randomUUID(); return `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function getStoragePathUrl(path: string) { return supabase.storage.from(evidencePhotosBucket).getPublicUrl(path).data.publicUrl; }
async function getDisplayUrl(path: string | null) { if (!path) return null; if (path.startsWith('http')) return path; const { data, error } = await supabase.storage.from(evidencePhotosBucket).createSignedUrl(path, 60 * 60); if (!error && data?.signedUrl) return data.signedUrl; return getStoragePathUrl(path); }
async function attachDisplayUrls(photos: JobHazardPhoto[]) { return Promise.all(photos.map(async (photo) => ({ ...photo, display_url: await getDisplayUrl(photo.photo_url), thumbnail_display_url: await getDisplayUrl(photo.thumbnail_url) }))); }
function loadImage(file: File) { return new Promise<HTMLImageElement>((resolve, reject) => { const image = new Image(); const objectUrl = URL.createObjectURL(file); image.onload = () => { URL.revokeObjectURL(objectUrl); resolve(image); }; image.onerror = () => { URL.revokeObjectURL(objectUrl); reject(new Error('Unable to read this image file.')); }; image.src = objectUrl; }); }
async function optimizeImage(file: File, maxWidth: number, quality: number): Promise<OptimizedImage> { const image = await loadImage(file); const scale = image.width > maxWidth ? maxWidth / image.width : 1; const width = Math.max(1, Math.round(image.width * scale)); const height = Math.max(1, Math.round(image.height * scale)); const canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height; const context = canvas.getContext('2d'); if (!context) throw new Error('Image optimization is not supported in this browser.'); context.drawImage(image, 0, 0, width, height); const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/jpeg', quality)); if (!blob) throw new Error('Image compression is not supported in this browser.'); return { blob, width, height, contentType: 'image/jpeg' }; }
function createHazardEntry(overrides: Partial<HazardEntry> = {}): HazardEntry { return { id: `${Date.now()}-${Math.random().toString(16).slice(2)}`, description: '', likelihood: 1, severity: 1, mitigation: '', owner: '', residualRisk: 'Low', notes: '', ...overrides }; }
function getInitialPpeRequirements(): PpeRequirements { return ppeOptions.reduce<PpeRequirements>((requirements, option) => ({ ...requirements, [option]: false }), {}); }
function getStoredArray(value: PpeValue | undefined) { return Array.isArray(value) ? value : []; }
function getStoredString(value: PpeValue | undefined) { return typeof value === 'string' ? value : ''; }
function splitStoredOption(value: string | null | undefined, options: string[]) { if (!value) return { option: '', other: '' }; return options.includes(value) ? { option: value, other: '' } : { option: 'Other', other: value }; }
function getEffectiveGroundSurface(formData: JhaFormState) { return formData.surfaceType === 'Other' ? formData.surfaceTypeOther.trim() : formData.surfaceType; }
function getEffectiveWorkSurface(formData: JhaFormState) { return formData.workSurfaceType === 'Other' ? formData.workSurfaceTypeOther.trim() : formData.workSurfaceType; }
function getRiskScore(entry: HazardEntry) { return entry.likelihood * entry.severity; }
function getRiskRating(score: number) { if (score >= 15) return 'High'; if (score >= 9) return 'Medium'; return 'Low'; }
function parseNullableNumber(value: string) { return value.trim() ? Number(value) : null; }
function formatDate(value: string) { if (!value) return 'Not scheduled'; const [year, month, day] = value.split('-'); return year && month && day ? `${month}/${day}/${year}` : value; }
function hasRunoffHazard(formData: JhaFormState) { return formData.hazardEntries.some((entry) => entry.description === 'Contaminated runoff entering storm drains or waterways'); }

function normalizeJobPersonnelAssignment(row: unknown): JobPersonnelAssignment {
  const assignment = row as JobPersonnelAssignment & { personnel: JobPersonnelAssignment['personnel'] | JobPersonnelAssignment['personnel'][] };
  return { ...assignment, personnel: Array.isArray(assignment.personnel) ? assignment.personnel[0] ?? null : assignment.personnel };
}

function normalizeJobEquipmentAssignment(row: unknown): JobEquipmentAssignment {
  const assignment = row as JobEquipmentAssignment & { equipment: JobEquipmentAssignment['equipment'] | JobEquipmentAssignment['equipment'][] };
  return { ...assignment, equipment: Array.isArray(assignment.equipment) ? assignment.equipment[0] ?? null : assignment.equipment };
}

function getAssignedEquipmentLabel(assignment: JobEquipmentAssignment) {
  const equipment = assignment.equipment;
  if (!equipment) return '';
  const makeModel = [equipment.make, equipment.model].filter(Boolean).join(' ').trim();
  return makeModel && makeModel !== equipment.name ? `${equipment.name} (${makeModel})` : equipment.name;
}

function buildMissionBasicsSourceData(job: Job, assignments: JobPersonnelAssignment[], equipmentAssignments: JobEquipmentAssignment[], operatorCompany: string): MissionBasicsSourceData {
  const rpicAssignment = assignments.find((assignment) => assignment.assigned_role === 'RPIC');
  const crewAssignments = assignments.filter((assignment) => assignment.assigned_role !== 'RPIC');
  const assignedDrones = equipmentAssignments.filter((assignment) => assignment.equipment?.equipment_type === 'Drone');
  const droneAssignments = assignedDrones.length > 0 ? assignedDrones : equipmentAssignments;

  return {
    operatorCompany,
    remotePilotInCommand: rpicAssignment?.personnel?.full_name ?? '',
    clientPropertyOwner: job.client_name ?? '',
    jobDate: job.planned_date ?? '',
    siteAddress: job.site_address?.trim() || job.location || '',
    dronePlatform: droneAssignments.map(getAssignedEquipmentLabel).filter(Boolean).join(', '),
    jobTypeScope: `${job.service_type} - ${job.name}`,
    crewMembers: crewAssignments.map((assignment) => `${assignment.personnel?.full_name ?? 'Personnel record unavailable'} (${assignment.assigned_role})`).join(', ')
  };
}

function getInitialFormState(job: Job | null, missionBasicsSource?: MissionBasicsSourceData): JhaFormState {
  return { operatorCompany: missionBasicsSource?.operatorCompany ?? '', jhaNumber: job ? `JHA-${job.id.slice(0, 8).toUpperCase()}` : '', remotePilotInCommand: missionBasicsSource?.remotePilotInCommand ?? '', datePrepared: today, clientPropertyOwner: missionBasicsSource?.clientPropertyOwner ?? '', jobDate: missionBasicsSource?.jobDate ?? job?.planned_date ?? today, siteAddress: missionBasicsSource?.siteAddress ?? job?.location ?? '', dronePlatform: missionBasicsSource?.dronePlatform ?? '', jobTypeScope: missionBasicsSource?.jobTypeScope ?? (job ? `${job.service_type} - ${job.name}` : ''), crewMembers: missionBasicsSource?.crewMembers ?? '', weatherConditions: '', faaAirspaceClass: '', surfaceType: '', surfaceTypeOther: '', workSurfaceType: '', workSurfaceTypeOther: '', buildingHeight: '', siteAccess: '', siteAccessConstraints: [], siteAccessOther: '', siteAccessNotes: '', windSpeed: '', weather: weatherOptions[0], visibility: visibilityOptions[0], publicPresence: false, exclusionZonePlanned: false, exclusionZoneDescription: '', runoffRisk: false, runoffContaminants: [], runoffContaminantOther: '', chemicalType: '', chemicalSdsReviewed: false, hazComCommunicationRequired: false, containmentPlan: '', regulatoryCitations: [], waterBodyProximity: false, waterBodyDistance: '', waterBodyType: waterBodyTypeOptions[0], secondaryContainmentInPlace: false, reclamationMethod: reclamationMethodOptions[0], reclamationVolumeEstimate: '', disposalVendorNameContact: '', laancRequired: laancOptions[2], hazardEntries: [], ppeRequirements: getInitialPpeRequirements(), nearestHospital: '', emergencyContact: '', droneIncidentProcedure: defaultIncidentProcedure, communicationMethods: [], communicationMethodOther: '', radioChannel: '', communicationPlanReviewed: false, lostCommunicationProcedureReviewed: false, crewBriefed: false, controlsInPlace: false, stopWorkAuthorityAcknowledged: false, assessorName: '', assessmentDate: today, rpicPrintedName: '', status: statusOptions[0] };
}
function normalizeHazards(value: unknown) { if (!Array.isArray(value)) return []; return value.map((entry) => { const item = entry as Partial<HazardEntry>; return createHazardEntry({ id: item.id || createHazardEntry().id, description: item.description ?? '', likelihood: Number(item.likelihood) || 1, severity: Number(item.severity) || 1, mitigation: item.mitigation ?? '', owner: item.owner ?? '', residualRisk: item.residualRisk ?? 'Low', notes: item.notes ?? '' }); }); }
function normalizePpe(value: unknown) { if (!value || typeof value !== 'object' || Array.isArray(value)) return getInitialPpeRequirements(); return { ...getInitialPpeRequirements(), ...(value as PpeRequirements) }; }
function toFormState(job: Job, assessment: JhaAssessment | null, missionBasicsSource: MissionBasicsSourceData): JhaFormState {
  const defaults = getInitialFormState(job, missionBasicsSource); if (!assessment) return defaults; const ppeRequirements = normalizePpe(assessment.ppe_requirements); const groundSurface = splitStoredOption(assessment.surface_type, groundSurfaceOptions); const workSurface = splitStoredOption(getStoredString(ppeRequirements.__workSurfaceType), workSurfaceOptions); const storedRunoffContaminants = getStoredArray(ppeRequirements.__runoffContaminants);
  return { ...defaults, operatorCompany: defaults.operatorCompany, jhaNumber: assessment.jha_number ?? defaults.jhaNumber, remotePilotInCommand: defaults.remotePilotInCommand, datePrepared: assessment.date_prepared ?? defaults.datePrepared, clientPropertyOwner: defaults.clientPropertyOwner, jobDate: defaults.jobDate, siteAddress: defaults.siteAddress, dronePlatform: defaults.dronePlatform, jobTypeScope: defaults.jobTypeScope, crewMembers: defaults.crewMembers, weatherConditions: assessment.weather_conditions ?? '', faaAirspaceClass: assessment.faa_airspace_class ?? '', surfaceType: groundSurface.option, surfaceTypeOther: groundSurface.other, workSurfaceType: workSurface.option, workSurfaceTypeOther: workSurface.other, buildingHeight: assessment.building_height?.toString() ?? '', siteAccess: assessment.site_access ?? '', siteAccessConstraints: getStoredArray(ppeRequirements.__siteAccessConstraints), siteAccessOther: getStoredString(ppeRequirements.__siteAccessOther), siteAccessNotes: (getStoredString(ppeRequirements.__siteAccessNotes) || assessment.site_access) ?? '', windSpeed: assessment.wind_speed?.toString() ?? '', weather: assessment.weather ?? defaults.weather, visibility: assessment.visibility ?? defaults.visibility, publicPresence: Boolean(assessment.public_presence), exclusionZonePlanned: Boolean(assessment.exclusion_zone_planned), exclusionZoneDescription: assessment.exclusion_zone_description ?? '', runoffRisk: Boolean(assessment.runoff_risk), runoffContaminants: storedRunoffContaminants.length > 0 ? storedRunoffContaminants : assessment.chemical_type ? ['Chemical product used'] : [], runoffContaminantOther: getStoredString(ppeRequirements.__runoffContaminantOther), chemicalType: assessment.chemical_type ?? '', chemicalSdsReviewed: Boolean(ppeRequirements.__chemicalSdsReviewed), hazComCommunicationRequired: Boolean(ppeRequirements.__hazComCommunicationRequired), containmentPlan: assessment.containment_plan ?? '', regulatoryCitations: assessment.regulatory_citations ?? [], waterBodyProximity: Boolean(assessment.water_body_proximity), waterBodyDistance: assessment.water_body_distance?.toString() ?? '', waterBodyType: assessment.water_body_type ?? defaults.waterBodyType, secondaryContainmentInPlace: Boolean(assessment.secondary_containment_in_place), reclamationMethod: assessment.reclamation_method ?? defaults.reclamationMethod, reclamationVolumeEstimate: assessment.reclamation_volume_estimate?.toString() ?? '', disposalVendorNameContact: assessment.disposal_vendor_name_contact ?? '', laancRequired: assessment.laanc_required ?? defaults.laancRequired, hazardEntries: normalizeHazards(assessment.hazard_entries), ppeRequirements, nearestHospital: assessment.nearest_hospital ?? '', emergencyContact: assessment.emergency_contact ?? '', droneIncidentProcedure: assessment.drone_incident_procedure ?? defaultIncidentProcedure, communicationMethods: getStoredArray(ppeRequirements.__communicationMethods), communicationMethodOther: getStoredString(ppeRequirements.__communicationMethodOther), radioChannel: getStoredString(ppeRequirements.__radioChannel), communicationPlanReviewed: Boolean(ppeRequirements.__communicationPlanReviewed), lostCommunicationProcedureReviewed: Boolean(ppeRequirements.__lostCommunicationProcedureReviewed), crewBriefed: Boolean(assessment.crew_briefed), controlsInPlace: Boolean(assessment.controls_in_place), stopWorkAuthorityAcknowledged: Boolean(assessment.stop_work_authority_acknowledged), assessorName: assessment.assessor_name ?? '', assessmentDate: assessment.assessment_date ?? defaults.assessmentDate, rpicPrintedName: assessment.rpic_printed_name ?? '', status: assessment.status ?? defaults.status };
}
function getStepCompletion(formData: JhaFormState) { return [Boolean(formData.jhaNumber && formData.jobDate && formData.siteAddress && formData.jobTypeScope), Boolean(getEffectiveGroundSurface(formData) && getEffectiveWorkSurface(formData) && formData.windSpeed && formData.weather && formData.visibility), Boolean(formData.faaAirspaceClass || formData.laancRequired), !formData.runoffRisk || Boolean(formData.containmentPlan), formData.hazardEntries.some((entry) => entry.description.trim() && entry.mitigation.trim()), Boolean(formData.assessorName && formData.assessmentDate)]; }

export function JobHazardAnalysisPage() {
  const { jobId } = useParams(); const [job, setJob] = useState<Job | null>(null); const [formData, setFormData] = useState<JhaFormState | null>(null); const [photosByHazardId, setPhotosByHazardId] = useState<Record<string, JobHazardPhoto[]>>({}); const [uploadingHazardId, setUploadingHazardId] = useState<string | null>(null); const [photoError, setPhotoError] = useState<string | null>(null); const [activeStep, setActiveStep] = useState(0); const [isLoading, setIsLoading] = useState(true); const [isSaving, setIsSaving] = useState(false); const [loadError, setLoadError] = useState<string | null>(null); const [saveError, setSaveError] = useState<string | null>(null); const [saveMessage, setSaveMessage] = useState<string | null>(null);
  useEffect(() => {
    let isMounted = true;

    async function loadJha() {
      if (!jobId) {
        setLoadError('Missing job id.');
        setIsLoading(false);
        return;
      }

      setIsLoading(true);
      setLoadError(null);
      setPhotoError(null);

      try {
        const jobQuery = supabase
          .from('jobs')
          .select('id, organization_id, name, service_type, location, planned_date, status, client_name, site_address')
          .eq('id', jobId)
          .maybeSingle();
        const assessmentQuery = supabase.from('jha_assessments').select('*').eq('job_id', jobId).maybeSingle();
        const photoQuery = supabase
          .from('job_hazard_photos')
          .select('*')
          .eq('job_id', jobId)
          .is('deleted_at', null)
          .order('created_at', { ascending: false });
        const assignmentsQuery = supabase
          .from('job_personnel')
          .select('id, assigned_role, personnel:personnel_id(full_name)')
          .eq('job_id', jobId)
          .order('created_at', { ascending: true });
        const equipmentAssignmentsQuery = supabase
          .from('job_equipment')
          .select('id, equipment:equipment_id(name, equipment_type, make, model)')
          .eq('job_id', jobId)
          .order('created_at', { ascending: true });

        const [jobResult, assessmentResult, photoResult, assignmentsResult, equipmentAssignmentsResult] = await Promise.all([
          jobQuery,
          assessmentQuery,
          photoQuery,
          assignmentsQuery,
          equipmentAssignmentsQuery
        ]);

        if (jobResult.error) throw jobResult.error;
        if (assessmentResult.error) throw assessmentResult.error;
        if (photoResult.error) throw photoResult.error;
        if (assignmentsResult.error) throw assignmentsResult.error;
        if (equipmentAssignmentsResult.error) throw equipmentAssignmentsResult.error;
        if (!jobResult.data) throw new Error('Job not found.');

        const loadedJob = jobResult.data as Job;
        const organizationSettings = await loadOrganizationSettingsById(loadedJob.organization_id);
        const missionBasicsSource = buildMissionBasicsSourceData(
          loadedJob,
          (assignmentsResult.data ?? []).map(normalizeJobPersonnelAssignment),
          (equipmentAssignmentsResult.data ?? []).map(normalizeJobEquipmentAssignment),
          organizationSettings?.companyName ?? ''
        );
        const signedPhotos = await attachDisplayUrls((photoResult.data ?? []) as JobHazardPhoto[]);
        const groupedPhotos = signedPhotos.reduce<Record<string, JobHazardPhoto[]>>((groups, photo) => {
          if (!photo.hazard_id) return groups;
          return { ...groups, [photo.hazard_id]: [...(groups[photo.hazard_id] ?? []), photo] };
        }, {});

        if (!isMounted) return;
        setJob(loadedJob);
        setFormData(toFormState(loadedJob, assessmentResult.data as JhaAssessment | null, missionBasicsSource));
        setPhotosByHazardId(groupedPhotos);
      } catch (error) {
        if (isMounted) setLoadError(getErrorMessage(error));
      } finally {
        if (isMounted) setIsLoading(false);
      }
    }

    void loadJha();

    return () => {
      isMounted = false;
    };
  }, [jobId]);

  const highestRiskScore = useMemo(() => formData?.hazardEntries.length ? Math.max(...formData.hazardEntries.map(getRiskScore), 0) : 0, [formData]); const overallRiskRating = getRiskRating(highestRiskScore);
  function updateField<T extends keyof JhaFormState>(field: T, value: JhaFormState[T]) { setFormData((current) => (current ? { ...current, [field]: value } : current)); setSaveMessage(null); }
  function updateHazard(index: number, field: keyof HazardEntry, value: string | number) { setFormData((current) => current ? { ...current, hazardEntries: current.hazardEntries.map((entry, entryIndex) => entryIndex === index ? { ...entry, [field]: value } : entry) } : current); setSaveMessage(null); }
  function addHazardFromSuggestion(hazard: (typeof commonHazards)[number]) { setFormData((current) => { if (!current || current.hazardEntries.some((entry) => entry.description === hazard[0])) return current; return { ...current, hazardEntries: [...current.hazardEntries, createHazardEntry({ description: hazard[0], likelihood: hazard[1], severity: hazard[2], owner: hazard[3], mitigation: hazard[4], residualRisk: getRiskRating(hazard[1] * hazard[2]) === 'High' ? 'Medium' : 'Low' })] }; }); setSaveMessage(null); }
  function addCustomHazard() { setFormData((current) => current ? { ...current, hazardEntries: [...current.hazardEntries, createHazardEntry()] } : current); setSaveMessage(null); }
  function removeHazard(index: number) { setFormData((current) => current ? { ...current, hazardEntries: current.hazardEntries.filter((_, entryIndex) => entryIndex !== index) } : current); setSaveMessage(null); }
  function toggleCitation(citation: string) { setFormData((current) => { if (!current) return current; const regulatoryCitations = current.regulatoryCitations.includes(citation) ? current.regulatoryCitations.filter((item) => item !== citation) : [...current.regulatoryCitations, citation]; return { ...current, regulatoryCitations }; }); setSaveMessage(null); }
  function toggleFormArrayField(field: 'runoffContaminants' | 'communicationMethods', value: string) { setFormData((current) => { if (!current) return current; const values = current[field].includes(value) ? current[field].filter((item) => item !== value) : [...current[field], value]; return { ...current, [field]: values }; }); setSaveMessage(null); }
  function togglePpe(option: string) { setFormData((current) => current ? { ...current, ppeRequirements: { ...current.ppeRequirements, [option]: !current.ppeRequirements[option] } } : current); setSaveMessage(null); }
  async function handleUploadHazardPhoto(entry: HazardEntry, file: File, options: HazardPhotoUploadOptions) { if (!job) return; setUploadingHazardId(entry.id); setPhotoError(null); try { const { data: userData, error: userError } = await supabase.auth.getUser(); if (userError) throw userError; if (!userData.user) throw new Error('You must be signed in to upload evidence photos.'); const optimized = await optimizeImage(file, maxEvidencePhotoWidth, evidencePhotoQuality); const thumbnail = await optimizeImage(file, thumbnailWidth, 0.76); const safeName = createSafeStorageName(); const basePath = `${job.organization_id}/${job.id}/${entry.id}`; const photoPath = `${basePath}/${safeName}.jpg`; const thumbnailPath = `${basePath}/${safeName}-thumb.jpg`; const { error: uploadError } = await supabase.storage.from(evidencePhotosBucket).upload(photoPath, optimized.blob, { contentType: optimized.contentType, upsert: false }); if (uploadError) throw uploadError; const { error: thumbnailError } = await supabase.storage.from(evidencePhotosBucket).upload(thumbnailPath, thumbnail.blob, { contentType: thumbnail.contentType, upsert: false }); if (thumbnailError) throw thumbnailError; const hazardIndex = formData?.hazardEntries.findIndex((hazard) => hazard.id === entry.id) ?? -1; const hazardName = entry.description.trim() || `Hazard ${hazardIndex + 1}`; const { data, error } = await supabase.from('job_hazard_photos').insert({ organization_id: job.organization_id, job_id: job.id, hazard_id: entry.id, hazard_name: hazardName, photo_url: photoPath, thumbnail_url: thumbnailPath, caption: options.caption.trim() || null, include_in_packet: options.includeInPacket, uploaded_by: userData.user.id }).select('*').single(); if (error) throw error; const [signedPhoto] = await attachDisplayUrls([data as JobHazardPhoto]); setPhotosByHazardId((current) => ({ ...current, [entry.id]: [signedPhoto, ...(current[entry.id] ?? [])] })); setSaveMessage('Evidence photo uploaded.'); } catch (error) { setPhotoError(getErrorMessage(error)); } finally { setUploadingHazardId(null); } }
  async function handleUpdateHazardPhoto(photo: JobHazardPhoto, updates: Pick<JobHazardPhoto, 'caption' | 'include_in_packet'>) { setPhotoError(null); const previousPhotos = photosByHazardId; setPhotosByHazardId((current) => ({ ...current, [photo.hazard_id ?? '']: (current[photo.hazard_id ?? ''] ?? []).map((item) => item.id === photo.id ? { ...item, ...updates } : item) })); const { error } = await supabase.from('job_hazard_photos').update(updates).eq('id', photo.id); if (error) { setPhotosByHazardId(previousPhotos); setPhotoError(getErrorMessage(error)); } }
  async function handleRemoveHazardPhoto(photo: JobHazardPhoto) { setPhotoError(null); const previousPhotos = photosByHazardId; setPhotosByHazardId((current) => ({ ...current, [photo.hazard_id ?? '']: (current[photo.hazard_id ?? ''] ?? []).filter((item) => item.id !== photo.id) })); const { error } = await supabase.from('job_hazard_photos').update({ deleted_at: new Date().toISOString() }).eq('id', photo.id); if (error) { setPhotosByHazardId(previousPhotos); setPhotoError(getErrorMessage(error)); } }
  function validateForm(requireCompletion: boolean) { if (!formData) return 'Unable to save this JHA.'; if (!requireCompletion) return null; if (!getEffectiveGroundSurface(formData)) return 'Ground / Staging Surface is required.'; if (!getEffectiveWorkSurface(formData)) return 'Work Surface / Structure Type is required.'; if (!formData.windSpeed.trim()) return 'Wind speed is required.'; if (!formData.weather) return 'Weather is required.'; if (!formData.visibility) return 'Visibility is required.'; if (!formData.faaAirspaceClass && !formData.laancRequired) return 'Airspace class or LAANC status is required.'; if (formData.siteAccessConstraints.includes('Other') && !formData.siteAccessOther.trim()) return 'Describe the other site access or operational constraint.'; if (formData.runoffRisk && formData.runoffContaminants.length === 0) return 'Select at least one potential runoff contaminant.'; if (formData.runoffContaminants.includes('Other') && !formData.runoffContaminantOther.trim()) return 'Describe the other potential runoff contaminant.'; if (formData.runoffContaminants.includes('Chemical product used') && !formData.chemicalType.trim()) return 'Chemical type is required when a chemical product is used.'; if (formData.runoffRisk && !formData.containmentPlan.trim()) return 'Containment plan is required when runoff risk is present.'; if (!formData.assessorName.trim()) return 'Assessor name is required.'; if (!formData.assessmentDate) return 'Assessment date is required.'; const completeHazards = formData.hazardEntries.filter((entry) => entry.description.trim() || entry.mitigation.trim()); if (completeHazards.length === 0) return 'Select or add at least one hazard.'; if (completeHazards.some((entry) => !entry.description.trim() || !entry.mitigation.trim())) return 'Each hazard needs a description and mitigation.'; if (formData.publicPresence && formData.exclusionZonePlanned && !formData.exclusionZoneDescription.trim()) return 'Describe the planned exclusion zone.'; if (formData.status === 'Complete') { if (formData.communicationMethods.includes('Other') && !formData.communicationMethodOther.trim()) return 'Describe the other communication method.'; if (!formData.crewBriefed || !formData.controlsInPlace || !formData.stopWorkAuthorityAcknowledged) return 'Complete the RPIC certification acknowledgments before marking the JHA complete.'; if (!formData.rpicPrintedName.trim()) return 'RPIC printed name is required before marking the JHA complete.'; } return null; }
  async function saveAssessment(options: { requireCompletion?: boolean; message?: string } = {}) { if (!job || !formData) return false; const validationError = validateForm(Boolean(options.requireCompletion)); if (validationError) { setSaveError(validationError); setSaveMessage(null); return false; } setIsSaving(true); setSaveError(null); setSaveMessage(null); try { const { data: userData, error: userError } = await supabase.auth.getUser(); if (userError) throw userError; if (!userData.user) throw new Error('You must be signed in to save a JHA.'); const ppeRequirements = { ...formData.ppeRequirements, __workSurfaceType: getEffectiveWorkSurface(formData), __siteAccessConstraints: formData.siteAccessConstraints, __siteAccessOther: formData.siteAccessOther.trim(), __siteAccessNotes: formData.siteAccessNotes.trim(), __runoffContaminants: formData.runoffContaminants, __runoffContaminantOther: formData.runoffContaminantOther.trim(), __chemicalSdsReviewed: formData.chemicalSdsReviewed, __hazComCommunicationRequired: formData.hazComCommunicationRequired, __communicationMethods: formData.communicationMethods, __communicationMethodOther: formData.communicationMethodOther.trim(), __radioChannel: formData.radioChannel.trim(), __communicationPlanReviewed: formData.communicationPlanReviewed, __lostCommunicationProcedureReviewed: formData.lostCommunicationProcedureReviewed }; const siteAccessSummary = [...formData.siteAccessConstraints.filter((constraint) => constraint !== 'Other'), formData.siteAccessConstraints.includes('Other') ? formData.siteAccessOther.trim() : '', formData.siteAccessNotes.trim()].filter(Boolean).join('; '); const { error } = await supabase.from('jha_assessments').upsert({ job_id: job.id, organization_id: job.organization_id, user_id: userData.user.id, operator_company: formData.operatorCompany.trim() || null, jha_number: formData.jhaNumber.trim() || null, remote_pilot_in_command: formData.remotePilotInCommand.trim() || null, date_prepared: formData.datePrepared || null, client_property_owner: formData.clientPropertyOwner.trim() || null, job_date: formData.jobDate || null, site_address: formData.siteAddress.trim() || null, drone_platform: formData.dronePlatform.trim() || null, job_type_scope: formData.jobTypeScope.trim() || null, crew_members: formData.crewMembers.trim() || null, weather_conditions: formData.weatherConditions.trim() || null, faa_airspace_class: formData.faaAirspaceClass || null, surface_type: getEffectiveGroundSurface(formData) || null, building_height: parseNullableNumber(formData.buildingHeight), site_access: siteAccessSummary || null, wind_speed: parseNullableNumber(formData.windSpeed), weather: formData.weather, visibility: formData.visibility, public_presence: formData.publicPresence, exclusion_zone_planned: formData.exclusionZonePlanned, exclusion_zone_description: formData.exclusionZoneDescription.trim() || null, runoff_risk: formData.runoffRisk, chemical_type: formData.runoffContaminants.includes('Chemical product used') ? formData.chemicalType.trim() || null : null, containment_plan: formData.containmentPlan.trim() || null, regulatory_citations: formData.regulatoryCitations, water_body_proximity: formData.waterBodyProximity, water_body_distance: parseNullableNumber(formData.waterBodyDistance), water_body_type: formData.waterBodyType || null, secondary_containment_in_place: formData.secondaryContainmentInPlace, reclamation_method: formData.reclamationMethod || null, reclamation_volume_estimate: parseNullableNumber(formData.reclamationVolumeEstimate), disposal_vendor_name_contact: formData.disposalVendorNameContact.trim() || null, laanc_required: formData.laancRequired, hazard_entries: formData.hazardEntries.map((entry) => ({ ...entry, riskScore: getRiskScore(entry) })), overall_risk_rating: overallRiskRating, ppe_requirements: ppeRequirements, nearest_hospital: formData.nearestHospital.trim() || null, emergency_contact: formData.emergencyContact.trim() || null, drone_incident_procedure: formData.droneIncidentProcedure.trim() || null, crew_briefed: formData.crewBriefed, controls_in_place: formData.controlsInPlace, stop_work_authority_acknowledged: formData.stopWorkAuthorityAcknowledged, assessor_name: formData.assessorName.trim() || null, assessment_date: formData.assessmentDate || null, rpic_printed_name: formData.rpicPrintedName.trim() || null, certified_at: formData.status === 'Complete' ? new Date().toISOString() : null, status: formData.status, updated_at: new Date().toISOString() }, { onConflict: 'job_id' }); if (error) throw error; setSaveMessage(options.message ?? 'Progress saved.'); return true; } catch (error) { setSaveError(getErrorMessage(error)); return false; } finally { setIsSaving(false); } }
  async function goToStep(stepIndex: number) { if (stepIndex === activeStep || isSaving) return; const saved = await saveAssessment({ message: 'Progress saved.' }); if (saved) setActiveStep(stepIndex); }
  async function goNext() { if (activeStep >= steps.length - 1) return; const saved = await saveAssessment({ message: 'Progress saved.' }); if (saved) setActiveStep((current) => Math.min(current + 1, steps.length - 1)); }
  async function goBack() { if (activeStep <= 0) return; const saved = await saveAssessment({ message: 'Progress saved.' }); if (saved) setActiveStep((current) => Math.max(current - 1, 0)); }
  async function handleSubmit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); await saveAssessment({ requireCompletion: true, message: 'JHA saved.' }); }
  if (isLoading) return <section className="rounded-xl border border-slate-200 bg-white p-4 text-sm text-slate-600 shadow-sm">Loading job hazard analysis...</section>;
  if (loadError || !job || !formData) return <section className="space-y-4"><Link className="text-sm font-medium text-brand-700 hover:text-brand-900" to={jobId ? `/jobs/${jobId}/hub` : '/jobs'}>Back to Job File</Link><div className="rounded-xl border border-red-200 bg-red-50 p-4 shadow-sm" role="alert"><h1 className="text-base font-semibold text-red-800">Unable to load JHA</h1><p className="mt-2 text-sm text-red-700">{loadError ?? 'Please try again.'}</p></div></section>;
  const stepCompletion = getStepCompletion(formData);
  return <section className="space-y-4"><Link className="text-sm font-medium text-brand-700 hover:text-brand-900" to={`/jobs/${job.id}/hub`}>Back to Job File</Link><div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:p-6"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="text-sm font-medium text-slate-500">Pillar 2: Risk Management</p><h1 className="mt-1 text-2xl font-semibold text-brand-900">Job Hazard Analysis</h1><p className="mt-2 text-sm text-slate-600">{job.name} - {job.service_type} - {formatDate(job.planned_date)}</p></div><div className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700"><span className="font-medium text-slate-900">Overall risk:</span> {overallRiskRating}</div></div></div><ProgressIndicator activeStep={activeStep} completedSteps={stepCompletion} onStepClick={goToStep} disabled={isSaving} />{highestRiskScore >= 15 ? <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-900 shadow-sm" role="alert">Risk score of 15 or higher detected. Reduce or document controls before this job proceeds.</div> : null}<form className="space-y-4" onSubmit={handleSubmit}><div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:p-6"><div className="mb-5 flex flex-col gap-1"><p className="text-sm font-medium text-slate-500">Step {activeStep + 1} of {steps.length}</p><h2 className="text-xl font-semibold text-brand-900">{steps[activeStep]}</h2></div>{activeStep === 0 ? <MissionBasicsStep formData={formData} updateField={updateField} isSaving={isSaving} jobId={job.id} /> : null}{activeStep === 1 ? <SiteConditionsStep formData={formData} updateField={updateField} isSaving={isSaving} /> : null}{activeStep === 2 ? <AirspaceStep formData={formData} updateField={updateField} isSaving={isSaving} /> : null}{activeStep === 3 ? <EnvironmentalStep formData={formData} updateField={updateField} toggleFormArrayField={toggleFormArrayField} toggleCitation={toggleCitation} isSaving={isSaving} /> : null}{activeStep === 4 ? <HazardsStep formData={formData} photosByHazardId={photosByHazardId} uploadingHazardId={uploadingHazardId} addHazardFromSuggestion={addHazardFromSuggestion} addCustomHazard={addCustomHazard} updateHazard={updateHazard} removeHazard={removeHazard} onUploadPhoto={handleUploadHazardPhoto} onUpdatePhoto={handleUpdateHazardPhoto} onRemovePhoto={handleRemoveHazardPhoto} isSaving={isSaving} /> : null}{activeStep === 5 ? <CertificationStep formData={formData} updateField={updateField} togglePpe={togglePpe} toggleFormArrayField={toggleFormArrayField} isSaving={isSaving} /> : null}</div>{saveError ? <p className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700" role="alert">{saveError}</p> : null}{photoError ? <p className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700" role="alert">{photoError}</p> : null}{saveMessage ? <p className="rounded-lg border border-green-200 bg-green-50 px-3 py-2 text-sm text-green-700" role="status">{saveMessage}</p> : null}<div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><button type="button" className="min-h-11 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-400 sm:py-2" onClick={goBack} disabled={isSaving || activeStep === 0}>Back</button><div className="flex flex-col gap-2 sm:flex-row"><button type="button" className="min-h-11 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:bg-slate-100 sm:py-2" onClick={() => saveAssessment({ message: 'Progress saved.' })} disabled={isSaving}>{isSaving ? 'Saving...' : 'Save Progress'}</button>{activeStep < steps.length - 1 ? <button type="button" className="min-h-11 rounded-lg bg-brand-700 px-4 py-3 text-sm font-medium text-white transition hover:bg-brand-900 disabled:cursor-not-allowed disabled:bg-slate-400 sm:py-2" onClick={goNext} disabled={isSaving}>{isSaving ? 'Saving...' : 'Next'}</button> : <button type="submit" className="min-h-11 rounded-lg bg-brand-700 px-4 py-3 text-sm font-medium text-white transition hover:bg-brand-900 disabled:cursor-not-allowed disabled:bg-slate-400 sm:py-2" disabled={isSaving}>{isSaving ? 'Saving...' : 'Save JHA'}</button>}</div></div></form></section>;
}

function ProgressIndicator({ activeStep, completedSteps, onStepClick, disabled }: { activeStep: number; completedSteps: boolean[]; onStepClick: (step: number) => void; disabled: boolean }) { return <nav className="rounded-xl border border-slate-200 bg-white p-3 shadow-sm" aria-label="JHA progress"><ol className="grid gap-2 sm:grid-cols-2 lg:grid-cols-6">{steps.map((step, index) => <li key={step}><button type="button" className={`min-h-11 w-full rounded-lg border px-3 py-2 text-left text-sm transition ${index === activeStep ? 'border-brand-700 bg-brand-50 text-brand-900' : 'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'}`} onClick={() => onStepClick(index)} disabled={disabled}><span className="block text-xs font-semibold uppercase text-slate-500">Step {index + 1}</span><span className="mt-1 block font-semibold">{step}</span><span className="mt-1 block text-xs">{completedSteps[index] ? 'Started' : 'Not started'}</span></button></li>)}</ol></nav>; }
type StepProps = { formData: JhaFormState; updateField: <T extends keyof JhaFormState>(field: T, value: JhaFormState[T]) => void; isSaving: boolean };
type MissionBasicsStepProps = StepProps & { jobId: string };
function MissionBasicsStep({ formData, updateField, isSaving, jobId }: MissionBasicsStepProps) {
  const jobFileLink = `/jobs/${jobId}`;
  const crewLink = `/jobs/${jobId}/hub#crew-assignment`;
  const equipmentLink = `/jobs/${jobId}/hub#equipment-assignment`;

  return (
    <div className="space-y-4">
      <div className="rounded-lg border border-blue-100 bg-blue-50 p-3 text-sm text-blue-900">
        Mission Basics verifies information already controlled by the Job File and organization records. Use the source edit links below when auto-filled values need to change.
      </div>
      <div className="grid gap-4 sm:grid-cols-2">
        <LockedField label="Operator / Company" value={formData.operatorCompany} helperText="Pulled from Settings" editHref="/settings" editLabel="Edit Settings" />
        <TextInput label="JHA Number" value={formData.jhaNumber} onChange={(value) => updateField('jhaNumber', value)} disabled={isSaving} />
        <LockedField label="Remote Pilot in Command" value={formData.remotePilotInCommand} helperText="Pulled from Crew Assignment" editHref={crewLink} editLabel="Edit Crew Assignment" />
        <TextInput label="Date Prepared" type="date" value={formData.datePrepared} onChange={(value) => updateField('datePrepared', value)} disabled={isSaving} />
        <LockedField label="Client / Property Owner" value={formData.clientPropertyOwner} helperText="Pulled from Job File" editHref={jobFileLink} editLabel="Edit Job File" />
        <LockedField label="Job Date" value={formData.jobDate} type="date" helperText="Pulled from Job File" editHref={jobFileLink} editLabel="Edit Job File" />
        <LockedField label="Site Address" value={formData.siteAddress} helperText="Pulled from Job File" editHref={jobFileLink} editLabel="Edit Job File" />
        <LockedField label="Drone Platform" value={formData.dronePlatform} helperText="Pulled from Equipment" editHref={equipmentLink} editLabel="Edit Equipment Assignment" />
        <LockedField label="Job Type / Scope" value={formData.jobTypeScope} helperText="Pulled from Job File" editHref={jobFileLink} editLabel="Edit Job File" />
        <LockedField label="Crew Members" value={formData.crewMembers} helperText="Pulled from Crew Assignment" editHref={crewLink} editLabel="Edit Crew Assignment" />
      </div>
    </div>
  );
}
function SiteConditionsStep({ formData, updateField, isSaving }: StepProps) { function toggleConstraint(constraint: string) { const constraints = formData.siteAccessConstraints.includes(constraint) ? formData.siteAccessConstraints.filter((item) => item !== constraint) : [...formData.siteAccessConstraints, constraint]; updateField('siteAccessConstraints', constraints); } return <div className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><SelectInput label="Ground / Staging Surface" value={formData.surfaceType} options={['', ...groundSurfaceOptions]} onChange={(value) => updateField('surfaceType', value)} disabled={isSaving} required />{formData.surfaceType === 'Other' ? <TextInput label="Custom ground / staging surface" value={formData.surfaceTypeOther} onChange={(value) => updateField('surfaceTypeOther', value)} disabled={isSaving} required /> : null}<SelectInput label="Work Surface / Structure Type" value={formData.workSurfaceType} options={['', ...workSurfaceOptions]} onChange={(value) => updateField('workSurfaceType', value)} disabled={isSaving} required />{formData.workSurfaceType === 'Other' ? <TextInput label="Custom work surface / structure type" value={formData.workSurfaceTypeOther} onChange={(value) => updateField('workSurfaceTypeOther', value)} disabled={isSaving} required /> : null}<TextInput label="Building height (feet)" type="number" value={formData.buildingHeight} onChange={(value) => updateField('buildingHeight', value)} disabled={isSaving} /><TextInput label="Wind speed (MPH)" type="number" value={formData.windSpeed} onChange={(value) => updateField('windSpeed', value)} disabled={isSaving} required /><SelectInput label="Weather" value={formData.weather} options={weatherOptions} onChange={(value) => updateField('weather', value)} disabled={isSaving} /><SelectInput label="Visibility" value={formData.visibility} options={visibilityOptions} onChange={(value) => updateField('visibility', value)} disabled={isSaving} /><TextInput label="Weather Conditions" value={formData.weatherConditions} onChange={(value) => updateField('weatherConditions', value)} disabled={isSaving} /></div><fieldset className="rounded-lg border border-slate-200 bg-slate-50 p-3"><legend className="px-1 text-sm font-medium text-slate-700">Site Access / Operational Constraints</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{siteConstraintOptions.map((constraint) => <Checkbox key={constraint} label={constraint} checked={formData.siteAccessConstraints.includes(constraint)} onChange={() => toggleConstraint(constraint)} disabled={isSaving} />)}</div>{formData.siteAccessConstraints.includes('Other') ? <div className="mt-3"><TextInput label="Custom site access / operational constraint" value={formData.siteAccessOther} onChange={(value) => updateField('siteAccessOther', value)} disabled={isSaving} /></div> : null}<div className="mt-3"><TextArea label="Additional site access / operational notes" value={formData.siteAccessNotes} onChange={(value) => updateField('siteAccessNotes', value)} disabled={isSaving} /></div></fieldset><div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><Checkbox label="Public presence" checked={formData.publicPresence} onChange={(checked) => updateField('publicPresence', checked)} disabled={isSaving} />{formData.publicPresence ? <div className="mt-3 space-y-3"><Checkbox label="Exclusion zone planned" checked={formData.exclusionZonePlanned} onChange={(checked) => updateField('exclusionZonePlanned', checked)} disabled={isSaving} />{formData.exclusionZonePlanned ? <TextArea label="Exclusion zone description" value={formData.exclusionZoneDescription} onChange={(value) => updateField('exclusionZoneDescription', value)} disabled={isSaving} /> : null}</div> : null}</div></div>; }
function AirspaceStep({ formData, updateField, isSaving }: StepProps) { return <div className="grid gap-4 sm:grid-cols-2"><SelectInput label="FAA Airspace Class" value={formData.faaAirspaceClass} options={['', ...airspaceOptions]} onChange={(value) => updateField('faaAirspaceClass', value)} disabled={isSaving} /><SelectInput label="LAANC required" value={formData.laancRequired} options={laancOptions} onChange={(value) => updateField('laancRequired', value)} disabled={isSaving} />{formData.laancRequired === 'Yes' ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900 sm:col-span-2">Keep LAANC authorization documentation in the job file before operations begin.</div> : null}</div>; }
function EnvironmentalStep({ formData, updateField, toggleFormArrayField, toggleCitation, isSaving }: StepProps & { toggleFormArrayField: (field: 'runoffContaminants' | 'communicationMethods', value: string) => void; toggleCitation: (citation: string) => void }) { const showEnvironmentalControls = formData.runoffRisk || formData.waterBodyProximity; const chemicalProductUsed = formData.runoffContaminants.includes('Chemical product used'); return <div className="space-y-4"><div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><Checkbox label="Runoff risk" checked={formData.runoffRisk} onChange={(checked) => updateField('runoffRisk', checked)} disabled={isSaving} />{formData.runoffRisk ? <div className="mt-3 space-y-4"><p className="rounded-lg border border-blue-100 bg-blue-50 p-3 text-sm text-slate-700">{environmentalRunoffHelperText}</p><fieldset><legend className="text-sm font-medium text-slate-700">Potential runoff contaminants</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{runoffContaminantOptions.map((option) => <Checkbox key={option} label={option} checked={formData.runoffContaminants.includes(option)} onChange={() => toggleFormArrayField('runoffContaminants', option)} disabled={isSaving} />)}</div></fieldset>{formData.runoffContaminants.includes('Other') ? <TextInput label="Other potential runoff contaminant" value={formData.runoffContaminantOther} onChange={(value) => updateField('runoffContaminantOther', value)} disabled={isSaving} /> : null}{chemicalProductUsed ? <div className="space-y-3 rounded-lg border border-amber-200 bg-amber-50 p-3"><div className="grid gap-4 sm:grid-cols-2"><TextInput label="Chemical type / product" value={formData.chemicalType} onChange={(value) => updateField('chemicalType', value)} disabled={isSaving} /><TextInput label="Containment plan" value={formData.containmentPlan} onChange={(value) => updateField('containmentPlan', value)} disabled={isSaving} /></div><div className="grid gap-2 sm:grid-cols-2"><Checkbox label="SDS reviewed" checked={formData.chemicalSdsReviewed} onChange={(checked) => updateField('chemicalSdsReviewed', checked)} disabled={isSaving} /><Checkbox label="HazCom / PPE communication reviewed" checked={formData.hazComCommunicationRequired} onChange={(checked) => updateField('hazComCommunicationRequired', checked)} disabled={isSaving} /></div></div> : <TextInput label="Containment plan" value={formData.containmentPlan} onChange={(value) => updateField('containmentPlan', value)} disabled={isSaving} />}</div> : null}</div><div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><Checkbox label="Water body proximity" checked={formData.waterBodyProximity} onChange={(checked) => updateField('waterBodyProximity', checked)} disabled={isSaving} />{formData.waterBodyProximity ? <div className="mt-3 grid gap-4 sm:grid-cols-2"><TextInput label="Water body distance (feet)" type="number" value={formData.waterBodyDistance} onChange={(value) => updateField('waterBodyDistance', value)} disabled={isSaving} /><SelectInput label="Water body type" value={formData.waterBodyType} options={waterBodyTypeOptions} onChange={(value) => updateField('waterBodyType', value)} disabled={isSaving} /></div> : null}</div>{showEnvironmentalControls ? <div className="space-y-4 rounded-lg border border-slate-200 bg-white p-3"><Checkbox label="Secondary containment in place" checked={formData.secondaryContainmentInPlace} onChange={(checked) => updateField('secondaryContainmentInPlace', checked)} disabled={isSaving} /><div className="grid gap-4 sm:grid-cols-2"><SelectInput label="Reclamation method" value={formData.reclamationMethod} options={reclamationMethodOptions} onChange={(value) => updateField('reclamationMethod', value)} disabled={isSaving} /><TextInput label="Reclamation volume estimate (gallons)" type="number" value={formData.reclamationVolumeEstimate} onChange={(value) => updateField('reclamationVolumeEstimate', value)} disabled={isSaving} />{formData.reclamationMethod === 'Third Party Vendor' ? <TextInput label="Disposal vendor name and contact" value={formData.disposalVendorNameContact} onChange={(value) => updateField('disposalVendorNameContact', value)} disabled={isSaving} /> : null}</div></div> : null}{showEnvironmentalControls ? <fieldset><legend className="text-sm font-medium text-slate-700">Regulatory citations</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{citationOptions.map((citation) => <label key={citation} className="rounded-lg border border-slate-200 bg-white p-3 text-sm text-slate-700"><span className="flex items-start gap-3 font-medium"><input className="mt-1 h-4 w-4 rounded border-slate-300 text-brand-700 focus:ring-brand-700" type="checkbox" checked={formData.regulatoryCitations.includes(citation)} onChange={() => toggleCitation(citation)} disabled={isSaving} /><span>{citation}</span></span><span className="mt-2 block text-xs leading-5 text-slate-500">{citationGuidance[citation]}</span></label>)}</div></fieldset> : <div className="rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-600">Advanced regulatory fields appear when runoff risk or water body proximity is selected.</div>}</div>; }
type HazardPhotoHandlers = {
  photosByHazardId: Record<string, JobHazardPhoto[]>;
  uploadingHazardId: string | null;
  onUploadPhoto: (entry: HazardEntry, file: File, options: HazardPhotoUploadOptions) => Promise<void>;
  onUpdatePhoto: (photo: JobHazardPhoto, updates: Pick<JobHazardPhoto, 'caption' | 'include_in_packet'>) => Promise<void>;
  onRemovePhoto: (photo: JobHazardPhoto) => Promise<void>;
};

function HazardsStep({ formData, photosByHazardId, uploadingHazardId, updateHazard, addHazardFromSuggestion, addCustomHazard, removeHazard, onUploadPhoto, onUpdatePhoto, onRemovePhoto, isSaving }: { formData: JhaFormState; updateHazard: (index: number, field: keyof HazardEntry, value: string | number) => void; addHazardFromSuggestion: (hazard: (typeof commonHazards)[number]) => void; addCustomHazard: () => void; removeHazard: (index: number) => void; isSaving: boolean } & HazardPhotoHandlers) { const runoffHazard = commonHazards.find((hazard) => hazard[0] === 'Contaminated runoff entering storm drains or waterways'); const runoffHazardAdded = hasRunoffHazard(formData); return <div className="space-y-5"><div><h3 className="text-base font-semibold text-brand-900">Common hazards</h3><p className="mt-1 text-sm text-slate-600">Select common drone cleaning hazards to add them with editable suggested controls.</p><p className="mt-2 rounded-lg border border-blue-100 bg-blue-50 p-3 text-sm text-slate-700">{runoffHelperText}</p>{formData.runoffRisk && runoffHazard && !runoffHazardAdded ? <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900"><p className="font-medium">Runoff risk was identified in Environmental.</p><p className="mt-1">Add the contaminated runoff hazard here to score likelihood, severity, and operational controls.</p><button type="button" className="mt-3 min-h-11 rounded-lg bg-brand-700 px-4 py-2 text-sm font-medium text-white transition hover:bg-brand-900 disabled:cursor-not-allowed disabled:bg-slate-400" onClick={() => addHazardFromSuggestion(runoffHazard)} disabled={isSaving}>Add Contaminated Runoff Hazard</button></div> : null}<div className="mt-3 grid gap-2 sm:grid-cols-2">{commonHazards.map((hazard) => { const selected = formData.hazardEntries.some((entry) => entry.description === hazard[0]); return <button key={hazard[0]} type="button" className={`rounded-lg border p-3 text-left text-sm transition ${selected ? 'border-brand-700 bg-brand-50 text-brand-900' : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'}`} onClick={() => addHazardFromSuggestion(hazard)} disabled={isSaving || selected}><span className="block font-semibold">{hazard[0]}</span><span className="mt-1 block text-xs text-slate-500">Suggested owner: {hazard[3]}</span></button>; })}</div></div><button type="button" className="min-h-11 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm font-medium text-slate-700 transition hover:bg-slate-50 sm:py-2" onClick={addCustomHazard} disabled={isSaving}>Add Custom Hazard</button>{formData.hazardEntries.length === 0 ? <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">Select a common hazard above or add a custom hazard to begin the risk assessment.</div> : null}{formData.hazardEntries.map((entry, index) => <HazardCard key={entry.id} entry={entry} index={index} photos={photosByHazardId[entry.id] ?? []} isUploadingPhoto={uploadingHazardId === entry.id} updateHazard={updateHazard} removeHazard={removeHazard} onUploadPhoto={onUploadPhoto} onUpdatePhoto={onUpdatePhoto} onRemovePhoto={onRemovePhoto} disabled={isSaving} />)}</div>; }
function HazardCard({ entry, index, photos, isUploadingPhoto, updateHazard, removeHazard, onUploadPhoto, onUpdatePhoto, onRemovePhoto, disabled }: { entry: HazardEntry; index: number; photos: JobHazardPhoto[]; isUploadingPhoto: boolean; updateHazard: (index: number, field: keyof HazardEntry, value: string | number) => void; removeHazard: (index: number) => void; disabled: boolean } & Pick<HazardPhotoHandlers, 'onUploadPhoto' | 'onUpdatePhoto' | 'onRemovePhoto'>) { const score = getRiskScore(entry); return <div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><h3 className="text-sm font-semibold text-brand-900">Hazard {index + 1}</h3><div className="flex items-center gap-2"><span className="rounded-full border border-slate-200 bg-white px-3 py-1 text-xs font-semibold text-slate-700">{getRiskRating(score)} - {score}</span><button type="button" className="text-sm font-medium text-red-700 disabled:text-slate-400" onClick={() => removeHazard(index)} disabled={disabled}>Remove</button></div></div><div className="mt-3 grid gap-4 sm:grid-cols-2"><TextArea label="Hazard description" value={entry.description} onChange={(value) => updateHazard(index, 'description', value)} disabled={disabled} /><TextArea label="Controls / Mitigation Measures" value={entry.mitigation} onChange={(value) => updateHazard(index, 'mitigation', value)} disabled={disabled} /><RangeSelect label="Likelihood" value={entry.likelihood} helper={probabilityHelp} onChange={(value) => updateHazard(index, 'likelihood', value)} disabled={disabled} /><RangeSelect label="Severity" value={entry.severity} helper={severityHelp} onChange={(value) => updateHazard(index, 'severity', value)} disabled={disabled} /><SelectInput label="Residual risk" value={entry.residualRisk} options={['Low', 'Medium', 'High']} onChange={(value) => updateHazard(index, 'residualRisk', value)} disabled={disabled} /><TextInput label="Notes / Owner" value={entry.owner} onChange={(value) => updateHazard(index, 'owner', value)} disabled={disabled} /><div className="sm:col-span-2"><TextArea label="Additional notes" value={entry.notes} onChange={(value) => updateHazard(index, 'notes', value)} disabled={disabled} /></div></div><HazardPhotoEvidence entry={entry} photos={photos} isUploading={isUploadingPhoto} disabled={disabled} onUploadPhoto={onUploadPhoto} onUpdatePhoto={onUpdatePhoto} onRemovePhoto={onRemovePhoto} /></div>; }
function HazardPhotoEvidence({ entry, photos, isUploading, disabled, onUploadPhoto, onUpdatePhoto, onRemovePhoto }: { entry: HazardEntry; photos: JobHazardPhoto[]; isUploading: boolean; disabled: boolean } & Pick<HazardPhotoHandlers, 'onUploadPhoto' | 'onUpdatePhoto' | 'onRemovePhoto'>) { const [caption, setCaption] = useState(''); const [includeInPacket, setIncludeInPacket] = useState(true); const uploadInputId = `hazard-${entry.id}-upload`; const cameraInputId = `hazard-${entry.id}-camera`; async function handleFileChange(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; await onUploadPhoto(entry, file, { caption, includeInPacket }); setCaption(''); setIncludeInPacket(true); } return <div className="mt-4 rounded-lg border border-slate-200 bg-white p-3"><div className="flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between"><div><h4 className="text-sm font-semibold text-brand-900">Add Photo Evidence</h4><p className="mt-1 text-xs text-slate-500">Attach proof that controls were implemented for this hazard.</p></div><span className="text-xs font-medium text-slate-500">{photos.length} photo{photos.length === 1 ? '' : 's'}</span></div><div className="mt-3 grid gap-3 sm:grid-cols-[1fr_auto]"><TextInput label="Caption / notes for next photo" value={caption} onChange={setCaption} disabled={disabled || isUploading} /><div className="flex items-end"><Checkbox label="Include in Packet" checked={includeInPacket} onChange={setIncludeInPacket} disabled={disabled || isUploading} /></div></div><div className="mt-3 flex flex-col gap-2 sm:flex-row"><input id={uploadInputId} className="hidden" type="file" accept="image/*" onChange={handleFileChange} disabled={disabled || isUploading} /><input id={cameraInputId} className="hidden" type="file" accept="image/*" capture="environment" onChange={handleFileChange} disabled={disabled || isUploading} /><label htmlFor={uploadInputId} className={`min-h-11 cursor-pointer rounded-lg border border-slate-300 bg-white px-4 py-3 text-center text-sm font-medium text-slate-700 transition hover:bg-slate-50 sm:py-2 ${disabled || isUploading ? 'pointer-events-none opacity-50' : ''}`}>Upload File</label><label htmlFor={cameraInputId} className={`min-h-11 cursor-pointer rounded-lg bg-brand-700 px-4 py-3 text-center text-sm font-medium text-white transition hover:bg-brand-900 sm:py-2 ${disabled || isUploading ? 'pointer-events-none opacity-50' : ''}`}>{isUploading ? 'Optimizing & Uploading...' : 'Take Photo'}</label></div>{photos.length > 0 ? <div className="mt-4 grid gap-3 sm:grid-cols-2">{photos.map((photo) => <HazardPhotoCard key={photo.id} photo={photo} disabled={disabled} onUpdatePhoto={onUpdatePhoto} onRemovePhoto={onRemovePhoto} />)}</div> : <p className="mt-3 rounded-lg border border-dashed border-slate-300 p-3 text-sm text-slate-500">No evidence photos attached to this hazard yet.</p>}</div>; }
function HazardPhotoCard({ photo, disabled, onUpdatePhoto, onRemovePhoto }: { photo: JobHazardPhoto; disabled: boolean } & Pick<HazardPhotoHandlers, 'onUpdatePhoto' | 'onRemovePhoto'>) { return <article className="overflow-hidden rounded-lg border border-slate-200 bg-slate-50"><img className="h-40 w-full object-cover" src={photo.thumbnail_display_url ?? photo.display_url ?? getStoragePathUrl(photo.thumbnail_url ?? photo.photo_url)} alt={photo.caption || `${photo.hazard_name} evidence photo`} /><div className="space-y-3 p-3"><label className="block text-sm font-medium text-slate-700">Caption<input className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-700 focus:ring-2 focus:ring-brand-100" defaultValue={photo.caption ?? ''} onBlur={(event) => void onUpdatePhoto(photo, { caption: event.target.value.trim() || null, include_in_packet: photo.include_in_packet })} disabled={disabled} /></label><p className="text-xs text-slate-500">Uploaded {photo.created_at ? new Date(photo.created_at).toLocaleString() : 'just now'}</p><Checkbox label="Include in Packet" checked={photo.include_in_packet} onChange={(checked) => void onUpdatePhoto(photo, { caption: photo.caption, include_in_packet: checked })} disabled={disabled} /><button type="button" className="min-h-11 rounded-lg border border-red-200 bg-white px-4 py-2 text-sm font-medium text-red-700 transition hover:bg-red-50 disabled:text-slate-400" onClick={() => void onRemovePhoto(photo)} disabled={disabled}>Remove Photo</button></div></article>; }
function CertificationStep({ formData, updateField, togglePpe, toggleFormArrayField, isSaving }: StepProps & { togglePpe: (option: string) => void; toggleFormArrayField: (field: 'runoffContaminants' | 'communicationMethods', value: string) => void }) { return <div className="space-y-5"><fieldset><legend className="text-sm font-medium text-slate-700">PPE Requirements</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{ppeOptions.map((option) => <Checkbox key={option} label={option} checked={Boolean(formData.ppeRequirements[option])} onChange={() => togglePpe(option)} disabled={isSaving} />)}</div></fieldset><div className="grid gap-4 sm:grid-cols-2"><TextInput label="Nearest Hospital" value={formData.nearestHospital} onChange={(value) => updateField('nearestHospital', value)} disabled={isSaving} /><TextInput label="Emergency Contact" value={formData.emergencyContact} onChange={(value) => updateField('emergencyContact', value)} disabled={isSaving} /><div className="sm:col-span-2"><TextArea label="Drone Incident Procedure" value={formData.droneIncidentProcedure} onChange={(value) => updateField('droneIncidentProcedure', value)} disabled={isSaving} /></div></div><div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><h3 className="text-base font-semibold text-brand-900">Communications</h3><fieldset className="mt-3"><legend className="text-sm font-medium text-slate-700">Communication Method</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{communicationOptions.map((option) => <Checkbox key={option} label={option} checked={formData.communicationMethods.includes(option)} onChange={() => toggleFormArrayField('communicationMethods', option)} disabled={isSaving} />)}</div></fieldset>{formData.communicationMethods.includes('Other') ? <div className="mt-3"><TextInput label="Other communication method" value={formData.communicationMethodOther} onChange={(value) => updateField('communicationMethodOther', value)} disabled={isSaving} /></div> : null}<div className="mt-4 grid gap-4 sm:grid-cols-2"><TextInput label="Radio frequency/channel assigned or discussed" value={formData.radioChannel} onChange={(value) => updateField('radioChannel', value)} disabled={isSaving} /><div className="space-y-3 sm:pt-7"><Checkbox label="Communication plan reviewed" checked={formData.communicationPlanReviewed} onChange={(checked) => updateField('communicationPlanReviewed', checked)} disabled={isSaving} /><Checkbox label="Lost communication procedure reviewed" checked={formData.lostCommunicationProcedureReviewed} onChange={(checked) => updateField('lostCommunicationProcedureReviewed', checked)} disabled={isSaving} /></div></div></div><div className="rounded-lg border border-slate-200 bg-slate-50 p-3"><p className="text-sm text-slate-600">RPIC certifies that hazards were assessed, controls are in place before work begins, crew members were briefed, and stop-work authority is retained.</p><div className="mt-4 space-y-3"><Checkbox label="Crew briefed on hazards, controls, PPE, emergency procedures, communications, and stop-work authority" checked={formData.crewBriefed} onChange={(checked) => updateField('crewBriefed', checked)} disabled={isSaving} /><Checkbox label="Controls are in place before operations begin" checked={formData.controlsInPlace} onChange={(checked) => updateField('controlsInPlace', checked)} disabled={isSaving} /><Checkbox label="RPIC stop-work authority acknowledged" checked={formData.stopWorkAuthorityAcknowledged} onChange={(checked) => updateField('stopWorkAuthorityAcknowledged', checked)} disabled={isSaving} /></div></div><div className="grid gap-4 sm:grid-cols-2"><TextInput label="Assessor name" value={formData.assessorName} onChange={(value) => updateField('assessorName', value)} disabled={isSaving} required /><TextInput label="Assessment date" type="date" value={formData.assessmentDate} onChange={(value) => updateField('assessmentDate', value)} disabled={isSaving} required /><TextInput label="RPIC Printed Name" value={formData.rpicPrintedName} onChange={(value) => updateField('rpicPrintedName', value)} disabled={isSaving} /><SelectInput label="Status" value={formData.status} options={statusOptions} onChange={(value) => updateField('status', value)} disabled={isSaving} /></div></div>; }

type FieldProps = { label: string; value: string; onChange: (value: string) => void; disabled?: boolean; required?: boolean };
function LockedField({ label, value, helperText, editHref, editLabel, type = 'text' }: { label: string; value: string; helperText: string; editHref: string; editLabel: string; type?: string }) {
  return (
    <label className="block text-sm font-medium text-slate-700">
      {label}
      <input className="mt-1 w-full rounded-lg border border-slate-200 bg-slate-100 px-3 py-3 text-base text-slate-700 outline-none sm:py-2 sm:text-sm" type={type} value={value} readOnly aria-readonly="true" />
      <span className="mt-1 flex flex-col gap-1 text-xs text-slate-500 sm:flex-row sm:items-center sm:justify-between">
        <span>{helperText}</span>
        <Link className="font-semibold text-brand-700 hover:text-brand-900" to={editHref}>{editLabel}</Link>
      </span>
    </label>
  );
}
function TextInput({ label, value, onChange, disabled, required, type = 'text' }: FieldProps & { type?: string }) { return <label className="block text-sm font-medium text-slate-700">{label}{required ? <span className="text-red-600"> *</span> : null}<input className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-3 text-base outline-none focus:border-brand-700 focus:ring-2 focus:ring-brand-100 sm:py-2 sm:text-sm" type={type} value={value} onChange={(event) => onChange(event.target.value)} disabled={disabled} /></label>; }
function TextArea({ label, value, onChange, disabled }: FieldProps) { return <label className="block text-sm font-medium text-slate-700">{label}<textarea className="mt-1 min-h-24 w-full rounded-lg border border-slate-300 px-3 py-3 text-base outline-none focus:border-brand-700 focus:ring-2 focus:ring-brand-100 sm:text-sm" value={value} onChange={(event) => onChange(event.target.value)} disabled={disabled} /></label>; }
function SelectInput({ label, value, options, onChange, disabled, required }: FieldProps & { options: string[] }) { return <label className="block text-sm font-medium text-slate-700">{label}{required ? <span className="text-red-600"> *</span> : null}<select className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-3 text-base outline-none focus:border-brand-700 focus:ring-2 focus:ring-brand-100 sm:py-2 sm:text-sm" value={value} onChange={(event) => onChange(event.target.value)} disabled={disabled}>{options.map((option) => <option key={option || 'blank'} value={option}>{option || 'Select one'}</option>)}</select></label>; }
function RangeSelect({ label, value, helper, onChange, disabled }: { label: string; value: number; helper: string[]; onChange: (value: number) => void; disabled?: boolean }) { return <label className="block text-sm font-medium text-slate-700">{label}<select className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-3 text-base outline-none focus:border-brand-700 focus:ring-2 focus:ring-brand-100 sm:py-2 sm:text-sm" value={value} onChange={(event) => onChange(Number(event.target.value))} disabled={disabled}>{[1, 2, 3, 4, 5].map((score) => <option key={score} value={score}>{score} - {helper[score - 1]}</option>)}</select></label>; }
function Checkbox({ label, checked, onChange, disabled }: { label: string; checked: boolean; onChange: (checked: boolean) => void; disabled?: boolean }) { return <label className="flex items-start gap-3 text-sm font-medium text-slate-700"><input className="mt-1 h-4 w-4 rounded border-slate-300 text-brand-700 focus:ring-brand-700" type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} disabled={disabled} /><span>{label}</span></label>; }
